#include <stdio.h>
#include <stdlib.h>

int cmp(const void *a, const void *b) {
    int x = *(const int *)a;
    int y = *(const int *)b;
    return y - x;
}

int main() {
    int N, K;
    scanf("%d %d", &N, &K);

    int notas[505];
    for (int i = 0; i < N; i++) {
        scanf("%d", &notas[i]);
    }

    qsort(notas, N, sizeof(int), cmp);

    printf("%d\n", notas[K - 1]);

    return 0;
}
